package br.com.mp.androidsecurity.scanner
import android.content.Context
import android.content.pm.PackageManager
import android.content.pm.ApplicationInfo
import br.com.mp.androidsecurity.model.*
class InstalledAppsScanner(private val c:Context){private val pm=c.packageManager;private val sensitive=setOf(android.Manifest.permission.CAMERA,android.Manifest.permission.RECORD_AUDIO,android.Manifest.permission.ACCESS_FINE_LOCATION,android.Manifest.permission.READ_CONTACTS,android.Manifest.permission.READ_SMS,android.Manifest.permission.SEND_SMS,android.Manifest.permission.READ_CALL_LOG,android.Manifest.permission.CALL_PHONE,android.Manifest.permission.SYSTEM_ALERT_WINDOW,android.Manifest.permission.REQUEST_INSTALL_PACKAGES);fun scan(acc:Set<String>,admins:Set<String>):List<InstalledAppInfo>{return pm.getInstalledPackages(PackageManager.GET_PERMISSIONS).mapNotNull{pkg->val ai=pkg.applicationInfo?:return@mapNotNull null;val req=pkg.requestedPermissions.orEmpty().filter{sensitive.contains(it)};val granted=req.filter{pm.checkPermission(it,pkg.packageName)==PackageManager.PERMISSION_GRANTED}.toSet();val f=req.map{s->PermissionFinding(s,s.substringAfterLast('.'),s in granted,RiskEngine.points(s))};val a=pkg.packageName in acc;val d=pkg.packageName in admins;val score=RiskEngine.score(req,granted,a,d);InstalledAppInfo(pkg.packageName,ai.loadLabel(pm).toString(),pkg.versionName,(ai.flags and ApplicationInfo.FLAG_SYSTEM)!=0,f,a,d,score,RiskEngine.level(score))}.sortedByDescending{it.riskScore}}